import heapq

def shortest_path(edges, start, end):
    """
    Find the shortest path between two nodes in a directed weighted graph.

    Args:
        edges: List of tuples (from_node, to_node, weight) representing one-way roads.
        start: Starting node.
        end: Ending node.

    Returns:
        Tuple (distance, path), where distance is the shortest total distance and
        path is an ordered list of nodes from start to end.
        If no path exists, returns (None, None).
        Raises ValueError if any edge has a negative weight.
    """

    # Handle case where start and end are the same
    if start == end:
        return (0, [start])

    # Check for negative weights and collect all nodes
    all_nodes = set()
    graph = {}
    for from_node, to_node, weight in edges:
        if weight < 0:
            raise ValueError("Negative edge weight detected")

        all_nodes.add(from_node)
        all_nodes.add(to_node)
        if from_node not in graph:
            graph[from_node] = []
        graph[from_node].append((to_node, weight))

    # Ensure both start and end are in the graph (even if isolated)
    for node in [start, end]:
        if node not in all_nodes:
            continue  # Not in any edge, treat as isolated but still valid input

    # Use Dijkstra's algorithm
    distances = {node: float('inf') for node in all_nodes}
    distances[start] = 0
    parent = {}

    priority_queue = [(0, start)]

    while priority_queue:
        current_dist, current_node = heapq.heappop(priority_queue)

        if current_dist > distances[current_node]:
            continue

        for neighbor, weight in graph.get(current_node, []):
            new_dist = current_dist + weight
            if new_dist < distances[neighbor]:
                distances[neighbor] = new_dist
                parent[neighbor] = current_node
                heapq.heappush(priority_queue, (new_dist, neighbor))

    # Check if the end is reachable
    if distances[end] == float('inf'):
        return (None, None)

    # Reconstruct path from start to end using parent pointers
    path = []
    current = end
    while current != start:
        path.append(current)
        current = parent[current]
    path.append(start)
    path.reverse()

    return (distances[end], path)
